  const language=()=>localStorage.getItem('vaak-language-'+(localStorage.getItem(session)||'guest'))||'es';
  const escape=text=>text.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  function apply(root=document.body){if(language()!=='es'||!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{const original=node.nodeValue;let value=original;terms.forEach(([from,to])=>value=value.replace(new RegExp(escape(from),'gi'),to));if(value!==original)node.nodeValue=value});document.querySelectorAll('[placeholder]').forEach(input=>{let original=input.placeholder,value=original;terms.forEach(([from,to])=>value=value.replace(new RegExp(escape(from),'gi'),to));if(value!==original)input.placeholder=value})}
